        assertTrue(ok && c.owner() == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        address ownerBefore = c.owner();
        address actor = address(uint160(uint256(keccak256(abi.encode(newOwner)))) | 1);
        vm.assume(actor != ownerBefore);
        vm.prank(actor);
        bool ok = c.setOwner(newOwner);
        assertTrue(ok == false && c.owner() == ownerBefore);
    }
}

